/////////////////////////////////////////////////////////////////////////////
// The result handle ThePartitionManager->bfmeForwardResultA() returns.
//
// Retail constructs it IN PLACE at [esp+0x30] (+0x008F) and destroys it inline
// after the loop (+0x0287), so the handle IS the payload: an STLport node-alloc
// vector of {Object*, pad} entries (begin/end/capacity), the cursor, and a
// reference count.  Retail reads +0x00/+0x04/+0x08 (+0x00A3), decs +0x10
// (+0x028B) and compares it against zero there.
/////////////////////////////////////////////////////////////////////////////

struct Rva000D77B0ResultEntry
{
	Object *object;
	unsigned int m_unmodelled_04;
};

void __cdecl __stlp_deallocate_small(void *pointer, UnsignedInt bytes);

struct BfmeResultA
{
	void *m_begin;
	void *m_end;
	void *m_capacity;
	Rva000D77B0ResultEntry *m_current;
	Int m_references;

	__forceinline ~BfmeResultA()
	{
		if (--m_references == 0)
		{
			void *begin = m_begin;
			if (begin != NULL)
			{
				Int bytes = (Int)((char *)m_capacity - (char *)begin);
				bytes = (bytes >> 3) << 3;
				if (bytes > 0x80)
					::operator delete(begin);
				else
					__stlp_deallocate_small(begin, bytes);
			}
			::operator delete(this);
		}
	}

	Object *next(Object *&object)
	{
		if (m_current == (Rva000D77B0ResultEntry *)m_end)
			return NULL;
		object = (m_current++)->object;
		return object;
	}
};

class BfmeResultForwardA
{
	unsigned char m_padding[0x0C];
	void *m_source;
public:
	BfmeResultA bfmeForwardResultA();
};

// +0x0230 / +0x024B: the retail body reads the time-of-day field of the global
// data at +0x218 (TIME_OF_DAY_NIGHT == 4).  No BFME layout witness covers
// GlobalData, so the offset is spelled out rather than named.
#define BfmeTimeOfDayOffset 0x218

// ?becomingLocalPlayer@Player@@QAEX_N@Z
void Player::becomingLocalPlayer(Bool yes)
{
	if (yes)
	{
		// This changes the color of the little dot on the upper right side of the screen indicating
		// which team is under control.
		if( TheGameClient )
		{
			RGBColor rgb;
			rgb.setFromInt(m_color);
			TheGameClient->setTeamColor((Int)(rgb.red*255), (Int)(rgb.green*255), (Int)(rgb.blue*255));
		}

		if( ThePartitionManager )
		{
			BfmeResultA iter = ((BfmeResultForwardA *)ThePartitionManager)->bfmeForwardResultA();
			Object *object;
			while (iter.next(object))
			{
				// Added support for updating the perceptions of garrisoned buildings containing enemy stealth units.
				// When changing teams, it is necessary to update this information.
				Rva000D77B0ContainSlice *contain =
					(Rva000D77B0ContainSlice *)*(void **)((char *)object + 0x1FC);
				if( contain )
				{
					contain->recalcApparentControllingPlayer();
					TheRadar->removeObject( object );
					TheRadar->addObject( object );
				}

				if( (*(UnsignedInt *)((char *)object + 0x130) & 0x800) != 0 )
				{
					//KM -- August 2002:
					//Added support for disguised objects, based on relationships, we either show the real color or the disguised color.
					static const NameKeyType key_SpecialDisguiseUpdate = NAMEKEY("SpecialDisguiseUpdate");
					Rva00267B10 *specialDisguise = (Rva00267B10 *)object->findUpdateModule(key_SpecialDisguiseUpdate);
					if (specialDisguise)
					{
						Team *team = *(Team **)((char *)object + 0x23C);
						specialDisguise->m00267B10(getRelationship(team) == ALLIES && isPlayerActive());
					}
				}

				const ThingTemplate *thingTemplate = *(const ThingTemplate **)((char *)object + 4);
				const Overridable *finalOverride;
				if (thingTemplate == NULL)
					finalOverride = NULL;
				else
					finalOverride = thingTemplate->getFinalOverride();
				if ((*(UnsignedInt *)((char *)finalOverride + 0xD0) & 0x800000) != 0)
				{
					Drawable *draw = ((Rva000D77B0ObjectView *)object)->getDrawable();
					if( draw )
					{
						static const NameKeyType key_StealthUpdate = NAMEKEY("StealthUpdate");
						Rva000D77B0StealthView *update = (Rva000D77B0StealthView *)object->findUpdateModule(key_StealthUpdate);

						if( update && update->isDisguised() )
						{
							Player *disguisedPlayer = ThePlayerList->getNthPlayer( update->getDisguisedPlayerIndex() );
							Team *team = *(Team **)((char *)object + 0x23C);
							if( getRelationship( team ) != ALLIES && isPlayerActive() )
							{
								//Neutrals and enemies will see this disguised unit as the team it's disguised as.
								if (*(Int *)((char *)TheGlobalData + BfmeTimeOfDayOffset) == TIME_OF_DAY_NIGHT)
									draw->setIndicatorColor(*(UnsignedInt *)((char *)disguisedPlayer + 0x1C8));
								else
									draw->setIndicatorColor(*(UnsignedInt *)((char *)disguisedPlayer + 0x1C4));
							}
							else
							{
								//Otherwise, the color will show up as the team it really belongs to.
								if (*(Int *)((char *)TheGlobalData + BfmeTimeOfDayOffset) == TIME_OF_DAY_NIGHT)
									draw->setIndicatorColor(object->getNightIndicatorColor());
								else
									draw->setIndicatorColor( object->getIndicatorColor() );
							}
							TheRadar->removeObject( object );
							TheRadar->addObject( object );
						}
					}
				}
			}
		}
	}
	else
	{
		// nothing to do
	}
}
